{"content":"<#
.SYNOPSIS
    Lightweight HttpListener-based REST API for the RAZOR Service Manager.
.DESCRIPTION
    Serves the web UI and exposes /api/services endpoints backed by
    ServiceManager.ps1. Depends on ServiceManager.ps1 and Logger.ps1.
#>

Import-Module "$PSScriptRoot/ServiceManager.ps1" -Force
Import-Module "$PSScriptRoot/Logger.ps1" -Force

function Start-ApiServer {
    param(
        [int]$Port = 8080,
        [string]$WebRoot = "$PSScriptRoot/../web"
    )

    $listener = [System.Net.HttpListener]::new()
    $listener.Prefixes.Add("http://localhost:$Port/")
    $listener.Start()
    Write-Log -Level INFO -Message "API server listening on http://localhost:$Port"

    while ($listener.IsListening) {
        $ctx = $listener.GetContext()
        try {
            Invoke-Route -Context $ctx -WebRoot $WebRoot
        } catch {
            Write-Log -Level ERROR -Message "Route error: $_"
            $ctx.Response.StatusCode = 500
        } finally {
            $ctx.Response.Close()
        }
    }
}

function Invoke-Route {
    param($Context, [string]$WebRoot)

    $path = $Context.Request.Url.AbsolutePath
    $method = $Context.Request.HttpMethod

    switch -Regex ($path) {
        '^/api/services$' {
            $data = Get-ServiceStatus | ConvertTo-Json -Depth 4
            Write-JsonResponse -Context $Context -Json $data
        }
        '^/api/services/(?<name>[^/]+)/start$' {
            $name = $Matches.name
            $data = Start-ManagedService -Name $name | ConvertTo-Json -Depth 4
            Write-JsonResponse -Context $Context -Json $data
        }
        '^/api/services/(?<name>[^/]+)/stop$' {
            $name = $Matches.name
            $data = Stop-ManagedService -Name $name | ConvertTo-Json -Depth 4
            Write-JsonResponse -Context $Context -Json $data
        }
        '^/api/logs$' {
            $data = Get-RecentLogs -Count 100 | ConvertTo-Json
            Write-JsonResponse -Context $Context -Json $data
        }
        default {
            Write-StaticFile -Context $Context -WebRoot $WebRoot -Path $path
        }
    }
}

function Write-JsonResponse {
    param($Context, [string]$Json)
    $bytes = [System.Text.Encoding]::UTF8.GetBytes($Json)
    $Context.Response.ContentType = "application/json"
    $Context.Response.OutputStream.Write($bytes, 0, $bytes.Length)
}

function Write-StaticFile {
    param($Context, [string]$WebRoot, [string]$Path)
    if ($Path -eq "/") { $Path = "/index.html" }
    $file = Join-Path $WebRoot ($Path.TrimStart("/"))
    if (Test-Path $file) {
        $bytes = [System.IO.File]::ReadAllBytes($file)
        $Context.Response.OutputStream.Write($bytes, 0, $bytes.Length)
    } else {
        $Context.Response.StatusCode = 404
    }
}

